// TerminalFocusMsg tells a view whether the terminal window has the focus
// (DEVDESK-210). The router sends it only to the view on screen: on a blur or
// focus edge, and when a view enters the screen.
//
// Resume is true only on the focus edge that follows a blur: the view may
// catch up on what it paused (a refresh tick, for example). A view entering
// the screen gets Resume false, and the message never asks for a scan, an
// Init or a footer message.
type TerminalFocusMsg struct {
	Focused bool
	Resume  bool
}
}

// RefreshTickMsg triggers a periodic refresh
type RefreshTickMsg time.Time

// Three clocks, and it's the measured cost that separates them: a gopsutil
// sample costs ≈ 5 ms, `docker stats --no-stream` ≈ 2 s, and the slow round
// (GitLab, `system df`, workspaces, tools) ≈ 600 ms plus the network. A single
// clock for all three would make the cheap call wait behind the expensive
// one.
const (
	hostTickInterval   = time.Second
	dockerTickInterval = 5 * time.Second
)

// HostTickMsg schedules the next host sample.
	loadingDocker     bool
	loadingOCI        bool
	loadingWorkspaces bool

	// measuringSize is not a loading flag: it **excludes** a second walk as
	// long as the first one hasn't answered. It's the only dashboard call
	// whose duration grows with the user's data, so the only one that can
	// overrun its interval — and two concurrent walks would double the I/O
	// for a figure already on its way.
	measuringSize bool

	// Refresh
	refreshInterval time.Duration

	// footer is the one line of transient state below the viewport (Rule 128).
	// The dashboard budgets an info line and left it permanently empty; a key
	// the header greys out has to be able to say why it declined (Rule 130).
	footer sharedcomponents.FooterMessage

	// jobs is the router's snapshot of what is running. The dashboard starts
	// none of it and shows only the count — it is the one screen a user is
	// likely to be looking at while a batch runs somewhere else, which is
	// exactly the case D67 made possible and D9 has to answer for.
	jobs []jobs.Run
}

// New creates a new dashboard model
func New(cfg *config.Config, state *shared.State) Model {
	return Model{
		config:            cfg,
		shared:            state,
		serviceStatus:     shared.ServiceStatusUnknown,
		loadingServices:   true,
		loadingForge:      true,
		loadingDocker:     true,
		loadingOCI:        true,
		loadingWorkspaces: true,
		// Init() starts the walk: the flag is therefore raised right at
		// construction, otherwise the first slow tick would start a second
		// one.
		measuringSize:   true,
		refreshInterval: time.Duration(cfg.Status.RefreshInterval) * time.Second,
	}
}

// Init initializes the dashboard by loading all data
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.checkServices(),
		m.fetchForgeStats(),
		m.fetchDockerStats(),
		m.fetchOCIStats(),
		m.fetchWorkspaceStats(),
		m.scheduleRefresh(),
		m.sampleHost(),
		m.scheduleHostTick(),
		m.fetchDockerMetrics(),
		m.scheduleDockerTick(),
		m.fetchDiskUsage(),
		m.measureWorkspaceSize(),
		m.fetchPosture(),
	)
}

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		// A terminal that grows up to `wide` puts the Resources boxes on
		// screen and removes the tab: staying on it would leave the view on a
		// tab that no longer exists.
		if m.activeTab >= dashboardTab(tabCountFor(layoutTier(m.width, m.height))) {
			m.activeTab = tabOverview
		}

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case jobs.ChangedMsg:
		m.jobs = msg.Runs
		return m, nil

	case jobs.FrameMsg:
		m.footer.SetSpinnerFrame(msg.RenderedFrame)
		return m, nil

	case StatusCheckMsg:
		return m.handleStatusCheck(msg)

	case ForgeStatsMsg:
		return m.handleForgeStats(msg)

	case DockerStatsMsg:
		return m.handleDockerStats(msg)

	case OCIStatsMsg:
		return m.handleOCIStats(msg)

	case WorkspaceStatsMsg:
		return m.handleWorkspaceStats(msg)

	case RefreshTickMsg:
		return m.alsoMeasuringSize(m.refreshAll())

	case HostTickMsg:
		return m, tea.Batch(m.sampleHost(), m.scheduleHostTick())

	case HostSampleMsg:
		return m.handleHostSample(msg)

	case DockerTickMsg:
		return m, tea.Batch(m.fetchDockerMetrics(), m.scheduleDockerTick())

	case DockerMetricsMsg:
		return m.handleDockerMetrics(msg)

	case DiskUsageMsg:
